**Describe the bug**
Rendering of custom dictionaries cannot be customized with `__rich_render__`.

**To Reproduce**
~~~~python
from collections import UserDict
import rich

class CustomDict(dict):
  def __rich_render__(s, c, o):
    yield rich.panel.Panel("success!")

class CustomDict2(UserDict):
  def __rich_render__(s, c, o):
    yield rich.panel.Panel("success!")

rich.print(CustomDict({1: 100}))
# => {1: 100}

rich.print(CustomDict2({2: 200}))
# => {2: 200}
~~~~

**Describe the bug**

Using the following class:

```py
from autoslot import SlotsMeta
from rich.progress import Progress

class meclair (SlotsMeta):
    def __init__(cls, *args, **kwargs):
        cls.Progress = Progress(auto_refresh=False)

class eclair(metaclass=meclair):
    def __init__(self, iterable, name, color):
        self.color = color
        self.iterable = tuple(iterable)
        self.len = len(iterable)
        self.increment = 100 / self.len
        self.n = 0
        self.name = name

        if len(self.__class__.Progress.task_ids) == 0:
            self.first_task = self.__class__.Progress.add_task(f"[green]start", total = 0, visible = False)

        self.task = self.__class__.Progress.add_task(f"[{self.color}]{self.name}", total = self.len, start = False)

    def __iter__(self):
        self.n = 0

        if len(self.__class__.Progress.task_ids) == 2:
            self.__class__.Progress.start()
            self.__class__.Progress.start_task(self.__class__.Progress.task_ids[1])
        else:
            self.__class__.Progress.start_task(self.task)

        return self

    def __next__(self):
        if self.n < self.len:
            try:
                self.__class__.Progress.update(self.task, advance = self.increment, refresh = True)
                return self.iterable[self.n]
            finally:
                self.n += 1
        else:
            try:
                raise StopIteration
            finally:
                self.__class__.Progress.stop_task(self.task)
                if self.__class__.Progress.finished:
                    self.__class__.Progress.stop()
```

