<summary>Repro script and output comparison between Rich and native tracebacks</summary>

```python
from exceptiongroup import ExceptionGroup  # backport; this is builtin from Python 3.11.0b1

def f():
    raise ValueError("From f()")

def g():
    raise RuntimeError("From g()")

def main():
    excs = []
    for callback in [f, g]:
        try:
            callback()
        except Exception as err:
            err.__notes__ = ["Added a note"]
            excs.append(err)
    if excs:
        raise ExceptionGroup("Oops", excs)

def test():
    try:
        main()
    except Exception as err:
        err.__notes__ = ["Added a note"]
        raise

if __name__ == "__main__":
    from rich.console import Console

    console = Console()
    try:
        test()
    except Exception:
        console.print_exception(show_locals=True)

    print("\n\n" + "=" * 70 + "\n\n")
    test()  # Show the native exception display
```
